import { ComponentType } from 'react';

export interface Issue {
  date: Date;
  Content: ComponentType;
}

const context = require.context('./issues', true, /\.tsx$/);

const issues: Issue[] = context.keys().map((key) => context<{ default: Issue }>(key).default);

export const getLatestIssue = (now: Date = new Date()): Issue | undefined =>
  issues
    .filter((issue) => issue.date <= now)
    .sort((a, b) => b.date.getTime() - a.date.getTime())[0];
